import json,itertools,collections,decimal
D=json.loads(context); qs=D['quotes']; skus=D['skus']; vend={v['id']:v for v in D['vendors']}
opts={s:[q for q in qs if q['sku']==s and q['quality']=='approved' and skus[s]['demand']<=q['units']<=skus[s]['demand']+2 and q['arrival']<=skus[s]['deadline']] for s in skus}
best=None
for sel in itertools.product(*(opts[s] for s in skus)):
 bysku={q['sku']:q for q in sel}
 if any(q['needs_same_vendor_sku'] and bysku[q['needs_same_vendor_sku']]['vendor']!=q['vendor'] for q in sel): continue
 if sum(q['carbon'] for q in sel)>D['carbon_cap']: continue
 units=collections.Counter(); gross=collections.Counter(); skset=collections.defaultdict(set)
 for q in sel: units[q['vendor']]+=q['units']; gross[q['vendor']]+=q['units']*q['unit_cents']; skset[q['vendor']].add(q['sku'])
 if len(units)<3 or any(units[v]>vend[v]['unit_cap'] for v in units): continue
 cost=0
 for v,u in units.items():
  c=vend[v]; g=gross[v]; m=g
  if u>=c['tier_units']: m=int((decimal.Decimal(g)*(10000-c['tier_bps'])/10000).quantize(decimal.Decimal('1'),rounding=decimal.ROUND_HALF_UP))
  cost+=m+(c['shipping_cents'] if g<c['free_shipping_gross'] else 0)-(c['rebate_cents'] if len(skset[v])>=2 and m>=c['rebate_merchandise_min'] else 0)

 if best is None or cost<best: best=cost
print(FINAL(str(best)))
